@push('page-script')
<script>
  const storeOutboundRows = @json($rowItems);
  const storeOutboundById = Object.fromEntries(storeOutboundRows.map(row => [row.id, row]));
  const escapeHtml = value => String(value ?? '-').replace(/[&<>'"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#039;', '"': '&quot;' }[char]));
  const formatDate = value => value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short', timeZone: 'Asia/Jakarta' }).format(new Date(value)) : '-';
  document.querySelectorAll('.js-store-outbound-detail').forEach(button => button.addEventListener('click', () => { const row = storeOutboundById[button.dataset.id]; if (!row) return; document.getElementById('storeOutboundDetailTitle').textContent = `Detail ${row.ecommerce_order_number !== '-' ? row.ecommerce_order_number : 'Store Outbound'}`; document.getElementById('storeOutboundDetailSubtitle').textContent = `${row.store_name || '-'} · ${row.source_label || '-'}`; const fields = [['Store', row.store_name], ['Sumber', row.source_label], ['Tipe Outbound', row.outbound_type_label], ['Order Ecommerce', row.ecommerce_order_number], ['Transaksi', row.payment_number], ['Store Return', row.store_return_number], ['Kurir', row.courier_name], ['No. Resi', row.shipping_number], ['Tanggal Pengiriman', formatDate(row.shipment_date)]]; document.getElementById('storeOutboundDetailMeta').innerHTML = fields.map(([label, value]) => `<div class="col-6 col-lg-3"><div class="detail-value"><span class="detail-label">${escapeHtml(label)}</span><span class="fw-semibold">${escapeHtml(value || '-')}</span></div></div>`).join(''); const details = Array.isArray(row.product_details) ? row.product_details : []; document.getElementById('storeOutboundDetailItems').innerHTML = details.length ? details.map(item => `<tr><td><div class="fw-semibold">${escapeHtml(item.product_name)}</div><small class="text-muted">${escapeHtml(item.product_code)}</small></td><td class="text-end">${Number(item.qty || 0).toLocaleString('id-ID')}</td><td class="text-end">${Number(item.rfid_count || 0).toLocaleString('id-ID')}</td><td>${escapeHtml(item.rfid_summary)}</td><td>${escapeHtml(item.released_by_summary)}</td></tr>`).join('') : '<tr><td colspan="5" class="text-center text-muted py-4">Tidak ada detail item.</td></tr>'; bootstrap.Modal.getOrCreateInstance(document.getElementById('storeOutboundDetailModal')).show(); }));
</script>
@endpush
